// WF-02: Form Ingress
// Validates inbound-lead-v1 schema, generates IDs, builds fingerprint.
// Normalizes form-encoded data into canonical shape.
// Pure ingress - no qualification logic.

const crypto = require('crypto');
const input = $input.first().json;

// --- Generate UUID v4 ---
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const correlationId = uuidv4();
const leadId = uuidv4();

// --- Normalize form-encoded data: convert string booleans, trim whitespace ---
const consentRaw = input.consent_to_contact;
const consent = typeof consentRaw === 'boolean' ? consentRaw :
                consentRaw === 'true' || consentRaw === '1' || consentRaw === 'on';

// --- Validate required fields ---
const fullName = (input.full_name || '').trim();
const email = (input.email || '').trim().toLowerCase();
const projectDesc = (input.project_description || '').trim();

const missingRequired = !fullName || !email || !projectDesc;
const invalidEmail = email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const missingConsent = consentRaw === undefined || consentRaw === null;

const isValid = !missingRequired && !invalidEmail && !missingConsent;

// --- Build fingerprint: deterministic SHA-256 hash of key fields ---
const fingerprintSource = JSON.stringify({
  full_name: fullName,
  email: email,
  project_description: projectDesc.substring(0, 200),
  company_name: (input.company_name || '').trim(),
  phone: (input.phone || '').trim()
});
const fingerprint = crypto.createHash('sha256').update(fingerprintSource).digest('hex');

// --- Timestamp ---
const receivedAt = new Date().toISOString();
const submissionId = input.submission_id || ('form_' + Date.now() + '_' + Math.random().toString(36).substring(2, 10));

// --- Build normalized payload for DB insert ---
const normalizedInput = {
  full_name: fullName,
  email: email,
  project_description: projectDesc,
  consent_to_contact: consent,
  company_name: (input.company_name || '').trim(),
  company_website: (input.company_website || '').trim(),
  job_title: (input.job_title || '').trim(),
  phone: (input.phone || '').trim(),
  country: (input.country || '').trim(),
  budget_range: (input.budget_range || 'NOT_PROVIDED').trim(),
  desired_timeline: (input.desired_timeline || '').trim(),
  service_interest: (input.service_interest || '').trim(),
  lead_source: (input.lead_source || '').trim(),
  utm_source: (input.utm_source || '').trim(),
  utm_medium: (input.utm_medium || '').trim(),
  utm_campaign: (input.utm_campaign || '').trim(),
  utm_term: (input.utm_term || '').trim(),
  utm_content: (input.utm_content || '').trim()
};

return {
  correlation_id: correlationId,
  lead_id: leadId,
  submission_id: submissionId,
  fingerprint: fingerprint,
  received_at: receivedAt,
  is_valid: isValid,
  missing_required: missingRequired,
  invalid_email: invalidEmail,
  missing_consent: missingConsent,
  ...normalizedInput
};
